ruleContent.content:
#chapter@html@js:
var html = result;
var t = html.indexOf('class=\"tjlm\"');
if (t > -1) {
  var d = html.indexOf('</div>', t);
  if (d > -1) html = html.substring(0, t - 6) + html.substring(d + 6);
}
var box = html.indexOf('readcons');
if (box === -1) box = html.indexOf('readconss');
if (box === -1) box = html.indexOf('duboxs');
if (box === -1) box = html.indexOf('chapterbo');
if (box === -1) box = html.indexOf('reakuang');
if (box > -1) {
  var bs = html.indexOf('>', box) + 1;
  var be = html.indexOf('</div>', bs);
  if (be > -1) html = html.substring(bs, be);
}
// 跳过来源行（支持 shidp / shid / hid 三种）
var srcEnd = -1;
var si = html.indexOf('shidp');
if (si > -1 && si < 100) {
  var pe = html.indexOf('</p>', si);
  if (pe > -1) srcEnd = pe + 4;
}
if (srcEnd === -1) {
  si = html.indexOf('shid');
  if (si === -1) si = html.indexOf('hid');
  if (si > -1 && si < 100) {
    var ae = html.indexOf('</article>', si);
    if (ae > -1) srcEnd = ae + 10;
  }
}
if (srcEnd > -1) html = html.substring(srcEnd);
html = html.split('</p>').join('\
');
html = html.split('<br/>').join('\
');
html = html.split('<br>').join('\
');
var out = '';
var inTag = false;
for (var ci = 0; ci < html.length; ci++) {
  var ch = html.charAt(ci);
  if (ch === '<') { inTag = true; continue; }
  if (ch === '>') { inTag = false; continue; }
  if (!inTag) out += ch;
}
var lines = out.split('\
');
var clean = [];
for (var li = 0; li < lines.length; li++) {
  var l = lines[li];
  var trimmed = l.replace(/\\u3000/g, '').replace(/ /g, '');
  if (trimmed && trimmed !== '→') clean.push(l);
}
result = clean.join('\
');

